// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/dualstack/templates", wrapper.ListDualstackTemplates)
	router.POST(options.BaseURL+"/dualstack/templates", wrapper.CreateDualstackTemplate)
	router.DELETE(options.BaseURL+"/dualstack/templates/:templateId", wrapper.DeleteDualstackTemplate)
	router.PATCH(options.BaseURL+"/dualstack/templates/:templateId", wrapper.UpdateDualstackTemplate)
	router.GET(options.BaseURL+"/dhcp/options", wrapper.ListDhcpOptions)
	router.POST(options.BaseURL+"/dhcp/options", wrapper.CreateDhcpOption)
	router.DELETE(options.BaseURL+"/dhcp/options/:optionId", wrapper.DeleteDhcpOption)
	router.PATCH(options.BaseURL+"/dhcp/options/:optionId", wrapper.UpdateDhcpOption)
	router.GET(options.BaseURL+"/dhcp/classes", wrapper.ListDhcpClasses)
	router.POST(options.BaseURL+"/dhcp/classes", wrapper.CreateDhcpClass)
	router.DELETE(options.BaseURL+"/dhcp/classes/:classId", wrapper.DeleteDhcpClass)
	router.PATCH(options.BaseURL+"/dhcp/classes/:classId", wrapper.UpdateDhcpClass)
	router.GET(options.BaseURL+"/dhcp/leases6", wrapper.ListDhcpLeases6)
	router.POST(options.BaseURL+"/auth/login", wrapper.AuthLogin)
	router.GET(options.BaseURL+"/auth/user/info", wrapper.GetAuthUserInfo)
	router.GET(options.BaseURL+"/user/info", wrapper.GetAuthUserInfoAlias)
	router.GET(options.BaseURL+"/auth/codes", wrapper.ListAuthCodes)
	router.POST(options.BaseURL+"/auth/logout", wrapper.LogoutAuth)
	router.GET(options.BaseURL+"/users", wrapper.ListUsers)
	router.POST(options.BaseURL+"/users", wrapper.CreateUser)
	router.DELETE(options.BaseURL+"/users/:userId", wrapper.DeleteUser)
	router.PATCH(options.BaseURL+"/users/:userId", wrapper.UpdateUser)
	router.GET(options.BaseURL+"/dashboard", wrapper.GetDashboardOverview)
	router.GET(options.BaseURL+"/logs", wrapper.ListLogs)
	router.GET(options.BaseURL+"/logs/tail", wrapper.StreamLogTail)
	router.GET(options.BaseURL+"/logs/top", wrapper.ListLogTop)
	router.GET(options.BaseURL+"/logs/qps", wrapper.GetLogQps)
	router.GET(options.BaseURL+"/audits", wrapper.ListOperationAudits)
	router.GET(options.BaseURL+"/logs/export", wrapper.ExportLogs)
	router.POST(options.BaseURL+"/dns/conf/apply", wrapper.ApplyDnsConf)
	router.GET(options.BaseURL+"/dns/settings", wrapper.GetDnsSettings)
	router.PUT(options.BaseURL+"/dns/settings", wrapper.UpdateDnsSettings)
	router.GET(options.BaseURL+"/dns/settings/ttl-overrides", wrapper.ListTtlOverrides)
	router.PUT(options.BaseURL+"/dns/settings/ttl-overrides", wrapper.UpsertTtlOverride)
	router.POST(options.BaseURL+"/dns/cache/flush", wrapper.FlushCache)
	router.POST(options.BaseURL+"/dns/diagnose", wrapper.DiagnoseDns)
	router.GET(options.BaseURL+"/dns/blocklists", wrapper.ListBlocklists)
	router.POST(options.BaseURL+"/dns/blocklists", wrapper.CreateBlocklist)
	router.DELETE(options.BaseURL+"/dns/blocklists/:listId", wrapper.DeleteBlocklist)
	router.POST(options.BaseURL+"/dns/blocklists/:listId", wrapper.SyncBlocklist)
	router.DELETE(options.BaseURL+"/dns/blocklists/:listId/entries", wrapper.DeleteBlocklistEntry)
	router.GET(options.BaseURL+"/dns/blocklists/:listId/entries", wrapper.ListBlocklistEntries)
	router.POST(options.BaseURL+"/dns/blocklists/:listId/entries", wrapper.AddBlocklistEntry)
	router.GET(options.BaseURL+"/dns/policy-groups", wrapper.ListPolicyGroups)
	router.POST(options.BaseURL+"/dns/policy-groups", wrapper.CreatePolicyGroup)
	router.POST(options.BaseURL+"/dns/policy-groups/:groupId/compile", wrapper.CompilePolicyGroup)
	router.GET(options.BaseURL+"/dns/zones", wrapper.ListDnsZones)
	router.POST(options.BaseURL+"/dns/zones", wrapper.CreateDnsZone)
	router.GET(options.BaseURL+"/dns/zones/:zoneId/records", wrapper.ListDnsRecords)
	router.POST(options.BaseURL+"/dns/zones/:zoneId/records", wrapper.CreateDnsRecord)
	router.GET(options.BaseURL+"/dns/zones/:zoneId/linked", wrapper.ListLinkedRecords)
	router.DELETE(options.BaseURL+"/dns/zones/:zoneId", wrapper.DeleteDnsZone)
	router.GET(options.BaseURL+"/dns/zones/:zoneId", wrapper.ExportDnsZone)
	router.GET(options.BaseURL+"/forward-rules", wrapper.ListForwardRules)
	router.POST(options.BaseURL+"/forward-rules", wrapper.CreateForwardRule)
	router.DELETE(options.BaseURL+"/forward-rules/:ruleId", wrapper.DeleteForwardRule)
	router.PATCH(options.BaseURL+"/forward-rules/:ruleId", wrapper.UpdateForwardRule)
	router.GET(options.BaseURL+"/upstreams", wrapper.ListUpstreams)
	router.POST(options.BaseURL+"/upstreams", wrapper.CreateUpstream)
	router.DELETE(options.BaseURL+"/upstreams/:upstreamId", wrapper.DeleteUpstream)
	router.PATCH(options.BaseURL+"/upstreams/:upstreamId", wrapper.UpdateUpstream)
	router.POST(options.BaseURL+"/reservations/bulk", wrapper.BulkReservations)
	router.GET(options.BaseURL+"/assets", wrapper.ListAssets)
	router.PUT(options.BaseURL+"/assets", wrapper.UpsertAsset)
	router.DELETE(options.BaseURL+"/assets/:mac", wrapper.DeleteAsset)
	router.GET(options.BaseURL+"/ledger", wrapper.ListLedger)
	router.POST(options.BaseURL+"/ledger", wrapper.ReserveAddress)
	router.POST(options.BaseURL+"/ledger/bind", wrapper.BindStatic)
	router.GET(options.BaseURL+"/subnets", wrapper.ListSubnets)
	router.POST(options.BaseURL+"/subnets", wrapper.CreateSubnet)
	router.DELETE(options.BaseURL+"/subnets/:subnetId", wrapper.DeleteSubnet)
	router.PATCH(options.BaseURL+"/subnets/:subnetId", wrapper.UpdateSubnet)
	router.GET(options.BaseURL+"/orgs", wrapper.ListOrgTree)
	router.POST(options.BaseURL+"/orgs", wrapper.CreateOrg)
	router.DELETE(options.BaseURL+"/orgs/:orgId", wrapper.DeleteOrg)
	router.PATCH(options.BaseURL+"/orgs/:orgId", wrapper.UpdateOrg)
	router.GET(options.BaseURL+"/system/info", wrapper.GetSystemInfo)
}

